insert into content_fleet (slug, sort, status, data)
values ($seed$track-type-tractors$seed$, 1, 'published', $seed${"name":"Track-Type Tractors","category":"Earthmoving","icon":"dozer","strapline":"Bulk push, ripping and the machine the business is named for","description":"Dozers do the work that sets up everything else — stripping, bulk push, ripping hard material ahead of the excavators, and trimming the benches and ramps the rest of the fleet runs on. Supplied wet with an operator who has worked a coal face, or dry against your own crew.","image":"dozer-d10t-refurbished","secondaryImage":"dozer-d9t-dusk","specs":[{"label":"Class","value":"D6 – D10"},{"label":"Operating weight","value":"20 – 70 t"},{"label":"Attachments","value":"Semi-U blade, single-shank ripper"},{"label":"Hire basis","value":"Wet or dry, monthly or contract"}],"applications":["Topsoil stripping and overburden push","Ripping weathered and hard material","Haul road formation and ramp construction","Stockpile trimming and tip-head maintenance"],"serviceSlug":"plant-hire"}$seed$::jsonb)
