do update set sort = excluded.sort, status = excluded.status, data = excluded.data;

insert into content_fleet (slug, sort, status, data)
values ($seed$tracked-excavators$seed$, 2, 'published', $seed${"name":"Tracked Excavators","category":"Earthmoving","icon":"excavator","strapline":"The production unit — everything else cycles around it","description":"The loading tool sets the pace of the whole operation. Excavator class is matched to bench height and hauler size so the fleet cycles cleanly rather than one machine waiting on another. Bucket or hammer, with quick-couplers where the work changes through the shift.","image":"excavator-coal-bench-fleet","secondaryImage":"liebherr-excavator-standby","specs":[{"label":"Class","value":"20 t – 75 t"},{"label":"Typical duty","value":"Bench loading, bulk cut, trenching"},{"label":"Attachments","value":"GP and rock buckets, hydraulic hammer"},{"label":"Hire basis","value":"Wet or dry, shift or contract"}],"applications":["Bench loading into haulers","Bulk excavation and selective digging","Drain and services excavation","Breaking with hydraulic hammer"],"serviceSlug":"bulk-earthworks"}$seed$::jsonb)
