do update set sort = excluded.sort, status = excluded.status, data = excluded.data;

insert into content_fleet (slug, sort, status, data)
values ($seed$articulated-haulers$seed$, 3, 'published', $seed${"name":"Articulated Haulers","category":"Earthmoving","icon":"hauler","strapline":"Matched to the haul, not to whatever is standing idle","description":"Hauler size is chosen against haul distance, gradient and the loading tool, so passes match the bucket and nobody is paying for a truck that spends the cycle waiting. Articulated units handle the ground conditions a rigid truck cannot.","image":"adt-lowbed-quarry-delivery","secondaryImage":"excavator-adt-loading-coal","specs":[{"label":"Class","value":"25 t – 40 t payload"},{"label":"Configuration","value":"6×6 articulated"},{"label":"Typical duty","value":"Overburden, product, rehandle"},{"label":"Hire basis","value":"Wet, per shift or contract"}],"applications":["Overburden haulage to dump","Product haulage to stockpile or plant","Rehandle and rehabilitation material","Layer works material on road construction"],"serviceSlug":"materials-handling"}$seed$::jsonb)
