insert into content_fleet (slug, sort, status, data)
values ($seed$motor-graders$seed$, 4, 'published', $seed${"name":"Motor Graders","category":"Site services","icon":"grader","strapline":"The cheapest productivity gain on most operations","description":"A maintained haul road cuts fuel burn and cycle time on every load that crosses it, and protects tyre and suspension spend that never appears as a line item until it does. Graders run a set circuit rather than being called when somebody complains.","image":"dozer-d9t-dusk","secondaryImage":"water-bowser-dust-suppression","specs":[{"label":"Typical duty","value":"Haul road and platform trim"},{"label":"Circuit","value":"Set frequency, not on complaint"},{"label":"Works with","value":"Water bowser and roller"},{"label":"Hire basis","value":"Standing maintenance contract"}],"applications":["Haul road blading and cross-fall reinstatement","Table and mitre drain cutting","Platform and laydown trim to level","Ramp maintenance on gradient"],"serviceSlug":"haul-road-construction"}$seed$::jsonb)
