do update set sort = excluded.sort, status = excluded.status, data = excluded.data;

insert into content_fleet (slug, sort, status, data)
values ($seed$water-bowsers$seed$, 5, 'published', $seed${"name":"Water Bowsers","category":"Site services","icon":"bowser","strapline":"Dust held to the limit without watering a ramp into a hazard","description":"Application rate is set to the road surface and the gradient rather than applied uniformly, because over-watering a ramp creates exactly the hazard the circuit is meant to remove. Bowsers run to a circuit alongside the grader.","image":"water-bowser-dust-suppression","specs":[{"label":"Capacity","value":"16 000 – 20 000 L"},{"label":"Typical duty","value":"Dust suppression circuits"},{"label":"Control","value":"Rate set to surface and gradient"},{"label":"Hire basis","value":"Wet, contract"}],"applications":["Haul road dust suppression","Load-out and tipping point control","Fallout limit compliance","Fire water on standby"],"serviceSlug":"site-services"}$seed$::jsonb)
