insert into content_fleet (slug, sort, status, data)
values ($seed$field-service-units$seed$, 6, 'published', $seed${"name":"Field Service Units","category":"Mechanical","icon":"hose","strapline":"Equipped to close a call-out on the first visit","description":"A second trip costs another shift. The response vehicles carry diagnostics, welding plant, a hose crimper with hose and fitting stock, fluid transfer with spill containment, and the consumables behind most breakdowns — so the majority of call-outs are finished without going back.","image":"leikah-response-vehicle","secondaryImage":"field-service-excavator-repair","specs":[{"label":"Availability","value":"24 hours, 365 days"},{"label":"On board","value":"Diagnostics, welding, hose crimping"},{"label":"Fluids","value":"Transfer and capture, spill kits"},{"label":"Response","value":"Dispatched with a confirmed ETA"}],"applications":["Breakdown response on live benches","Hydraulic hose made and fitted at the machine","Field welding of structures and mountings","Scheduled servicing on site"],"serviceSlug":"breakdown-response"}$seed$::jsonb)
