where not exists (select 1 from content_faqs where data->>'seedKey' = $seed$faq-areas$seed$);

update content_faqs set sort = 1, data = $seed${"question":"Which areas do you work in?","answer":"The yard is in Middelburg and most work sits inside the Mpumalanga coalfields — Middelburg, Witbank/eMalahleni, Hendrina, Ogies, Kriel, Belfast, Delmas and Secunda. We mobilise further for contract work; the quotation states the mobilisation cost so there is nothing to discover later.","category":"General","seedKey":"faq-areas"}$seed$::jsonb
