where not exists (select 1 from content_faqs where data->>'seedKey' = $seed$faq-hours$seed$);

update content_faqs set sort = 2, data = $seed${"question":"What are your operating hours?","answer":"The workshop and offices run Monday to Friday 07:00–17:00 and Saturday 07:00–13:00. Breakdown dispatch does not keep office hours — the emergency line is answered around the clock, every day of the year, including public holidays.","category":"General","seedKey":"faq-hours"}$seed$::jsonb
