insert into content_faqs (sort, status, data)
select 14, 'published', $seed${"question":"How does a planned maintenance contract work?","answer":"We audit your fleet, build a service matrix per machine against your production calendar, and execute services to the hour meter on site or in the workshop. Oil samples are drawn at each service and trended per component, so a developing failure is flagged while it is still a service item. You get a monthly report covering availability, cost per hour, defect backlog and upcoming component changes.","category":"Maintenance","serviceSlug":"preventive-maintenance","seedKey":"faq-pm-contract"}$seed$::jsonb
where not exists (select 1 from content_faqs where data->>'seedKey' = $seed$faq-pm-contract$seed$);

