insert into content_news (slug, sort, status, data)
values ($seed$haul-road-maintenance-cheapest-productivity-gain$seed$, 0, 'published', $seed${"title":"The haul road is the cheapest productivity gain on most sites","excerpt":"Rolling resistance is paid on every cycle of every shift. Very few interventions return as much for as little as holding a road to its profile.","body":"Ask a production meeting where the next percentage point of throughput is coming from and the answers are usually expensive: another hauler, a bigger excavator, more operators. The cheapest answer is almost always already on site, and it is the road.\n\n## Rolling resistance is a tax on every load\n\nEvery percentage point of rolling resistance costs fuel and cycle time on every single load that crosses the surface. Unlike a machine purchase, the cost is invisible — it never appears as a line item, it just quietly raises the cost per tonne on everything.\n\nA road that has lost its cross-fall holds water in the wheel path. Water softens the layer, the wheel path deepens, and the deeper path holds more water. The failure is self-accelerating, which is why patching it after the fact never quite catches up.\n\n## Tyres and struts are the bill you actually see\n\nRock in the wheel path is what takes a tyre out before its hours. Corrugation and potholes load suspension struts in ways they were never designed for. Those costs do land as line items, but by the time they do, the road has been bad for months.\n\n## What holding a road actually requires\n\nThree things, none of them dramatic:\n\n- A wearing course that is maintained to thickness rather than allowed to wear through to the layer beneath.\n- Cross-fall trimmed on a set frequency so the surface sheds water instead of holding it.\n- Drains that are cut and kept open, discharging clear of the formation rather than back onto it.\n\nThe grader pass that does this is not glamorous and it does not show up in a production report. It shows up in fuel, in tyres, and in the cycle time that the plan assumed you would get.\n\n## Do it on a frequency, not on a complaint\n\nThe operations that keep their roads are the ones that grade to a schedule. The ones that lose them are the ones that grade when somebody complains. By the time a haul truck driver complains, the wearing course is already gone.","category":"Operations","author":"Leikah Plant Hire","publishedAt":"2025-07-14","image":"dozer-d9t-dusk","featured":true,"status":"published"}$seed$::jsonb)
on conflict (slug) where slug is not null and deleted_at is null
do update set sort = excluded.sort, status = excluded.status, data = excluded.data;

insert into content_news (slug, sort, status, data)
values ($seed$what-an-honest-strip-report-contains$seed$, 0, 'published', $seed${"title":"What an honest strip report should contain — and why you should insist on one","excerpt":"A rebuild quoted before the unit is stripped is a guess. Here is what the report you approve should actually show you.","body":"The most expensive words in a workshop are \"we'll sort it out as we go\". A rebuild scope that is not built on measurement grows every week you ask about it, and neither side ends up happy.\n\n## Measure first, quote second\n\nAn engine or transmission should be stripped completely, cleaned and measured before a single part is ordered. Bores, journals, decks, bearing housings, gears, shafts and carriers all have OEM service limits. Either a component is inside them or it is not, and that is a number, not an opinion.\n\n## What the report should show you\n\n- **Measurements against service limits**, component by component, so you can see what is worn and by how much.\n- **Photographs** of the significant findings, not a general shot of the bench.\n- **A line-by-line parts schedule** with OEM and approved-equivalent options priced separately where an equivalent is being offered.\n- **Machining scope** stated explicitly, including who is doing it and what it will take.\n- **A turnaround date** built on the actual lead times, not on optimism.\n\n## Why it protects both sides\n\nWith that report in hand, you are approving a defined scope at a defined price. The workshop is protected too — nobody is arguing later about work that was always going to be necessary but was never written down.\n\n## The build sheet matters just as much\n\nWhen the unit is assembled, torque, clearance and end-float should be recorded at every critical joint. If a question arises in twelve months, there is a figure to check against instead of a memory. Ask for the build sheet with the completed job. Any workshop that hesitates has told you something.","category":"Workshop","author":"Leikah Plant Hire","publishedAt":"2025-05-28","image":"engine-block-machined","featured":true,"status":"published"}$seed$::jsonb)
on conflict (slug) where slug is not null and deleted_at is null
do update set sort = excluded.sort, status = excluded.status, data = excluded.data;

insert into content_news (slug, sort, status, data)
values ($seed$planning-component-changes-on-oil-analysis$seed$, 0, 'published', $seed${"title":"Planning component changes on evidence instead of on failure","excerpt":"Oil analysis moves component replacement from an emergency into a budget line. The mechanism is simpler than it sounds.","body":"Unplanned failure costs several times what the same repair costs when it is planned — in emergency parts pricing, in recovery, and in the production that stops while it is all arranged. Oil analysis is the least expensive way to move that spend from unplanned to planned.\n\n## Trends, not single results\n\nA single oil result tells you very little. Read in isolation, a slightly elevated iron figure could be anything. Read as the fourth rising result in a row on the same component, it is a bearing or a gear set telling you what it intends to do.\n\nThe discipline is therefore trending: sample at every service, on the same component, and plot the result. Wear metals, silicon and viscosity are the three that carry most of the signal.\n\n## What each one is telling you\n\n- **Wear metals** — iron, copper, chrome, aluminium — point to which internal surface is deteriorating.\n- **Silicon** usually means dirt ingress. That is a filtration or a seal problem, and it will destroy a component far faster than normal wear.\n- **Viscosity** drifting off grade suggests fuel dilution, contamination, or oil that has simply been in service too long.\n\n## From a rising trend to a booked slot\n\nA rising trend triggers a physical inspection. An inspection that confirms it books the unit into the workshop at a time that suits your production plan. Parts are ordered at normal lead times rather than at emergency rates, and the machine comes off when you can afford to lose it.\n\nThat is the whole mechanism. It is not complicated, and it does not require new technology. It requires sampling every time and actually reading the trend when the results come back.","category":"Maintenance","author":"Leikah Plant Hire","publishedAt":"2025-03-19","image":"adt-transmission-assembly","featured":false,"status":"published"}$seed$::jsonb)
on conflict (slug) where slug is not null and deleted_at is null
do update set sort = excluded.sort, status = excluded.status, data = excluded.data;


