insert into site_settings (key, value, description)
values ($seed$seo.defaults$seed$, $seed${"titleTemplate":"%s — Leikah Plant Hire","defaultTitle":"Leikah Plant Hire — Plant Hire, Earthmoving & Heavy Mechanical | Middelburg","defaultDescription":"Leikah Plant Hire is a Middelburg-based plant hire, earthmoving and heavy mechanical contractor serving the Mpumalanga coalfields and the industrial corridor around them. We move bulk material, build and hold haul roads, and keep heavy fleets in production through scheduled maintenance and 24-hour breakdown response."}$seed$::jsonb, $seed$Fallback title and description for pages with no SEO override.$seed$)
